class Solution {
    public int[] smallerNumbersThanCurrent(int[] nums) {
        int[] counts = new int[101];
        for (int value : nums) {
            counts[value]++;
        }

        int[] smaller = new int[101];
        for (int value = 1; value <= 100; value++) {
            smaller[value] = smaller[value - 1] + counts[value - 1];
        }

        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            answer[i] = smaller[nums[i]];
        }
        return answer;
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int[] smallerNumbersThanCurrent(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);

        Map<Integer, Integer> firstSmallerCount = new HashMap<>();
        for (int i = 0; i < sorted.length; i++) {
            firstSmallerCount.putIfAbsent(sorted[i], i);
        }

        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            answer[i] = firstSmallerCount.get(nums[i]);
        }
        return answer;
    }
}

import java.util.Arrays;

class Solution {
    public int[] smallerNumbersThanCurrent(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);

        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            answer[i] = lowerBound(sorted, nums[i]);
        }
        return answer;
    }

    private int lowerBound(int[] sorted, int target) {
        int left = 0;
        int right = sorted.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (sorted[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public int[] smallerNumbersThanCurrent(int[] nums) {
        Fenwick tree = new Fenwick(101);
        for (int value : nums) {
            tree.add(value + 1, 1);
        }

        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            answer[i] = tree.prefix(nums[i]);
        }
        return answer;
    }

    private static class Fenwick {
        private final int[] tree;

        Fenwick(int size) {
            tree = new int[size + 1];
        }

        void add(int index, int delta) {
            while (index < tree.length) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        int prefix(int index) {
            int sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }
}

class Solution {
    public int[] smallerNumbersThanCurrent(int[] nums) {
        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int count = 0;
            for (int value : nums) {
                if (value < nums[i]) {
                    count++;
                }
            }
            answer[i] = count;
        }
        return answer;
    }
